(()=>{var e=document.querySelectorAll("[data-inview]");if(e.length)if("IntersectionObserver"in window){let r=new IntersectionObserver(e=>{e.forEach(e=>{var t;e.isIntersecting&&((t=e.target.dataset.inview)&&e.target.classList.add(t),r.unobserve(e.target))})},{threshold:.25});e.forEach(e=>{r.observe(e)})}else e.forEach(e=>{e.classList.add(e.dataset.inview)})})();